export const preferredCountryIsoList = ['sg', 'cn', 'us', 'gb', 'hk'];

export function findCountryByCodeOrIso(codeOrIso?: string): CountryPhoneItem {
  if (!codeOrIso) {
    return allCountryPhoneList.find(c => c.iso2 === 'sg') || allCountryPhoneList[0];
  }
  const clean = codeOrIso.replace('+', '').toLowerCase();
  // Match iso first
  const byIso = allCountryPhoneList.find(c => c.iso2.toLowerCase() === clean);
  if (byIso) return byIso;
  // Match dial code
  const byDial = allCountryPhoneList.find(c => c.dialCode === clean || c.code === codeOrIso);
  if (byDial) return byDial;
  return allCountryPhoneList.find(c => c.iso2 === 'sg') || allCountryPhoneList[0];
}
